window.__EPHONE_HTML_PARTS[15] = "    <div id=\"mcp-screen\" class=\"screen mcp-screen\">\n      <div class=\"header mcp-header\">\n        <span class=\"back-btn\" onclick=\"showScreen('home-screen')\">‹</span>\n        <span>MCP 连接</span>\n        <button type=\"button\" class=\"mcp-header-add\" id=\"mcp-add-connection-btn\" aria-label=\"添加连接\" title=\"添加连接\">+</button>\n      </div>\n      <div class=\"mcp-summary\" aria-live=\"polite\">\n        <div>\n          <strong id=\"mcp-summary-title\">尚未连接</strong>\n          <span id=\"mcp-summary-detail\">不会预装服务，由你连接自己的 MCP</span>\n        </div>\n        <span class=\"mcp-summary-dot\" id=\"mcp-summary-dot\"></span>\n      </div>\n      <div class=\"mcp-tabs\" role=\"tablist\" aria-label=\"MCP 页面\">\n        <button type=\"button\" class=\"mcp-tab active\" data-mcp-tab=\"connections\" role=\"tab\" aria-selected=\"true\">连接</button>\n        <button type=\"button\" class=\"mcp-tab\" data-mcp-tab=\"capabilities\" role=\"tab\" aria-selected=\"false\">能力</button>\n        <button type=\"button\" class=\"mcp-tab\" data-mcp-tab=\"activity\" role=\"tab\" aria-selected=\"false\">活动</button>\n        <button type=\"button\" class=\"mcp-tab\" data-mcp-tab=\"settings\" role=\"tab\" aria-selected=\"false\">设置</button>\n      </div>\n      <div class=\"mcp-scroll\" id=\"mcp-content\"></div>\n      <input id=\"mcp-import-input\" type=\"file\" accept=\"application/json,.json\" hidden>\n      <div class=\"mcp-sheet-backdrop\" id=\"mcp-sheet-backdrop\" aria-hidden=\"true\">\n        <section class=\"mcp-sheet\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"mcp-sheet-title\">\n          <div class=\"mcp-sheet-header\">\n            <button type=\"button\" class=\"mcp-sheet-close\" id=\"mcp-sheet-close\" aria-label=\"关闭\">×</button>\n            <strong id=\"mcp-sheet-title\"></strong>\n            <span class=\"mcp-sheet-header-spacer\"></span>\n          </div>\n          <div class=\"mcp-sheet-body\" id=\"mcp-sheet-body\"></div>\n          <div class=\"mcp-sheet-actions\" id=\"mcp-sheet-actions\"></div>\n        </section>\n      </div>\n    </div>\n    <div id=\"search-history-screen\" class=\"screen\">\n      <div class=\"header\"> <span class=\"back-btn\" id=\"search-history-back-btn\">‹</span> <span>搜索聊天记录</span> <span style=\"width: 30px;\"></span> </div>\n      <div id=\"search-bar\" style=\"padding: 10px 15px; border-bottom: 1px solid var(--border-color); background-color: var(--secondary-bg); flex-shrink: 0;\">\n        <div style=\"display: flex; gap: 10px; margin-bottom: 10px;\"> <input type=\"search\" id=\"keyword-search-input\" placeholder=\"输入关键词...\" style=\"flex-grow: 1; padding: 8px 12px; border: 1px solid var(--border-color); border-radius: 6px; font-size: 16px;\"> <input type=\"date\" id=\"date-search-input\"\n            style=\"padding: 8px 12px; border: 1px solid var(--border-color); border-radius: 6px; font-size: 16px;\"> </div>\n        <div style=\"display: flex; gap: 10px;\"> <button id=\"execute-search-btn\" class=\"form-button\" style=\"margin-top: 0; flex-grow: 1;\">搜索</button> <button id=\"clear-search-btn\" class=\"form-button form-button-secondary\" style=\"margin-top: 0; flex-grow: 1;\">重置</button> </div>\n      </div>\n      <div id=\"chat-search-results-list\" class=\"list-container\" style=\"padding: 15px; display: flex; flex-direction: column; gap: 15px;\"> </div>\n    </div>\n<!-- 支付宝屏幕 -->\n<div id=\"alipay-screen\" class=\"screen\">\n    <div class=\"alipay-header-area\">\n        <div class=\"alipay-nav\">\n            <span class=\"back-btn\" onclick=\"showScreen('home-screen')\">‹</span>\n            <span class=\"alipay-title\">支付宝</span>\n            <div style=\"display: flex; align-items: center; gap: 15px;\">\n                <span id=\"alipay-theme-toggle-btn\" class=\"alipay-action\" onclick=\"toggleAlipayTheme()\" title=\"切换主题\">\n                    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"18\" height=\"18\" style=\"vertical-align: middle;\">\n                        <path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"></path>\n                    </svg>\n                </span>\n                <span class=\"alipay-action\" onclick=\"handleUserTopUp()\">充值</span>\n            </div>\n        </div>\n    </div>\n    \n    <div class=\"alipay-card-container\">\n        <div class=\"alipay-balance-card\">\n            <div class=\"balance-label\">\n                <span>总资产(CNY)</span>\n                </div>\n            <div class=\"balance-amount\" id=\"alipay-balance-display\">0.00</div>\n            <div class=\"balance-status-tag\" id=\"alipay-status-tag\">标准会员</div>\n        </div>\n\n        <div class=\"alipay-grid-menu\">\n            <div class=\"alipay-menu-item\" onclick=\"openFundScreen()\">\n                <div class=\"menu-icon\">📈</div>\n                <div class=\"menu-info\">\n                    <div class=\"menu-title\">基金理财</div>\n                    <div class=\"menu-trend\" id=\"fund-market-trend-preview\" style=\"font-size:12px;\">+2.35%</div>\n                </div>\n                <div class=\"menu-arrow\">›</div>\n            </div>\n            </div>\n        \n        </div>\n\n    <div class=\"alipay-bill-container\" style=\"margin: 0 12px; border-radius: 16px;\">\n        <div id=\"alipay-transaction-list\">\n            </div>\n    </div>\n</div>\n<!-- 基金理财屏幕 (已去掉了内联颜色，改为 class 控制) -->\n<div id=\"fund-screen\" class=\"screen\" style=\"background-color: #f5f5f5;\">\n    <!-- 头部：添加了 class=\"fund-header-area\" -->\n    <div class=\"header fund-header-area\">\n        <span class=\"back-btn\" onclick=\"showScreen('alipay-screen')\" style=\"color: white;\">‹</span>\n        <span>理财市场</span>\n        <span class=\"action-btn\" onclick=\"refreshFundMarket()\" style=\"font-size: 14px; color: white;\">刷新</span>\n    </div>\n    \n    <!-- 资产卡片：添加了 class=\"fund-asset-card\" -->\n    <div class=\"fund-asset-card\">\n        <div style=\"font-size: 13px; opacity: 0.8;\">持有总资产 (CNY)</div>\n        <div style=\"font-size: 32px; font-weight: 700; margin: 5px 0;\" id=\"fund-total-assets\">0.00</div>\n        <div style=\"font-size: 13px; display: flex; gap: 15px;\">\n            <span>昨日收益 <span id=\"fund-yesterday-profit\">0.00</span></span>\n            <span>持有收益 <span id=\"fund-total-profit\">0.00</span></span>\n        </div>\n    </div>\n\n    <div class=\"list-container\" style=\"padding: 20px 15px; padding-bottom: 80px; background-color: #f5f5f5; border-radius: 20px 20px 0 0; overflow-y: auto; margin-top: -20px;\">\n        <div class=\"frame-tabs\" style=\"background: white; border-radius: 12px; padding: 5px; margin-bottom: 15px; border: none; box-shadow: 0 2px 8px rgba(0,0,0,0.05);\">\n            <div id=\"tab-fund-market\" class=\"frame-tab active\" onclick=\"switchFundTab('market')\" style=\"border-radius: 8px;\">市场热门</div>\n            <div id=\"tab-fund-my\" class=\"frame-tab\" onclick=\"switchFundTab('my')\" style=\"border-radius: 8px;\">我的持仓</div>\n        </div>\n\n        <div id=\"fund-market-list\" style=\"display: block;\"></div>\n        <div id=\"fund-my-list\" style=\"display: none;\"></div>\n        \n        <p style=\"font-size: 12px; color: #999; text-align: center; margin-top: 20px;\">\n            市场有风险，投资需谨慎<br>模拟数据仅供娱乐\n        </p>\n    </div>\n</div>\n\n<!-- 基金交易弹窗 -->\n<div id=\"fund-trade-modal\" class=\"modal\">\n    <div class=\"modal-content\" style=\"width: 300px; height: auto;\">\n        <div class=\"modal-header\">\n            <span id=\"fund-trade-title\">基金交易</span>\n        </div>\n        <div class=\"modal-body\">\n            <div style=\"margin-bottom: 15px; padding: 10px; background: #f9f9f9; border-radius: 8px;\">\n                <div id=\"fund-trade-name\" style=\"font-weight: bold; font-size: 16px;\"></div>\n                <div id=\"fund-trade-code\" style=\"font-size: 12px; color: #999;\"></div>\n                <div style=\"display: flex; justify-content: space-between; margin-top: 8px;\">\n                    <span style=\"font-size: 13px;\">当前净值: <span id=\"fund-trade-nav\" style=\"color: #1677ff; font-weight: bold;\"></span></span>\n                    <span style=\"font-size: 13px;\">日涨跌: <span id=\"fund-trade-change\"></span></span>\n                </div>\n            </div>\n            \n            <div class=\"form-group\">\n                <label id=\"fund-trade-label\">买入金额 (余额: ¥<span id=\"fund-wallet-balance\"></span>)</label>\n                <!-- 修复：强制 type=\"number\" -->\n                <input type=\"number\" id=\"fund-trade-amount\" placeholder=\"请输入金额\" style=\"font-size: 24px; font-weight: bold; color: #1677ff; border-bottom: 2px solid #eee; padding: 10px 0;\">\n            </div>\n            <p id=\"fund-trade-info\" style=\"font-size: 12px; color: #666; margin-top: 5px;\"></p>\n        </div>\n        <div class=\"modal-footer\">\n            <button class=\"cancel\" onclick=\"document.getElementById('fund-trade-modal').classList.remove('visible')\">取消</button>\n            <!-- 修复：直接绑定 onclick 函数，不再依赖 addEventListener -->\n            <button class=\"save\" id=\"fund-confirm-btn\" onclick=\"handleFundTradeConfirm()\">确认</button>\n        </div>\n    </div>\n</div>\n<div id=\"auction-screen\" class=\"screen\" style=\"background-color: #121212; color: #e0e0e0;\">\n    <div class=\"header\" style=\"background-color: #1c1c1e; color: #d4af37; border-bottom: 1px solid #333;\">\n    <span class=\"back-btn\" onclick=\"showScreen('home-screen')\" style=\"color: #d4af37;\">‹</span>\n    <span>黑市拍卖</span>\n    <div class=\"header-actions\">\n        <span class=\"action-btn\" onclick=\"generateNewAuctionItem()\">新拍品</span>\n        <span class=\"action-btn\" onclick=\"openInventoryModal()\">📦 仓库</span>\n        \n    </div>\n   </div>\n    \n    <!-- 拍品展示区 -->\n    <div id=\"auction-main-display\" style=\"padding: 20px; text-align: center; height: 45%; display: flex; flex-direction: column; align-items: center; justify-content: center;\">\n        <div id=\"auction-item-image-container\" style=\"width: 200px; height: 200px; border: 2px solid #d4af37; border-radius: 10px; overflow: hidden; box-shadow: 0 0 20px rgba(212, 175, 55, 0.3); background: #000; margin-bottom: 15px; position: relative;\">\n            <img id=\"auction-item-img\" src=\"\" style=\"width: 100%; height: 100%; object-fit: cover; display: none;\">\n            <div id=\"auction-loading\" style=\"color: #666; margin-top: 90px;\">等待拍品...</div>\n        </div>\n        <h2 id=\"auction-item-name\" style=\"margin: 5px 0; font-size: 20px; color: #fff;\">---</h2>\n        <p id=\"auction-item-desc\" style=\"font-size: 12px; color: #888; margin: 0; max-height: 40px; overflow: hidden;\">---</p>\n    </div>\n\n    <!-- 竞价信息区 -->\n    <div style=\"background-color: #1c1c1e; padding: 15px; border-radius: 20px 20px 0 0; flex-grow: 1; display: flex; flex-direction: column; box-shadow: 0 -4px 20px rgba(0,0,0,0.5);\">\n        \n        <div style=\"display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 10px; padding-bottom: 10px; border-bottom: 1px solid #333;\">\n            <div>\n                <div style=\"font-size: 12px; color: #888;\">当前最高价</div>\n                <div id=\"auction-current-price\" style=\"font-size: 32px; font-weight: bold; color: #ff4d4f; font-family: monospace;\">¥ 0</div>\n            </div>\n            <div style=\"text-align: right;\">\n                <div style=\"font-size: 12px; color: #888;\">倒计时</div>\n                <div id=\"auction-timer\" style=\"font-size: 24px; font-weight: bold; color: #d4af37;\">--</div>\n            </div>\n        </div>\n\n        <!-- 实时出价记录 -->\n        <div id=\"auction-log\" style=\"flex-grow: 1; overflow-y: auto; font-size: 13px; margin-bottom: 15px; height: 100px;\">\n            <div style=\"color: #666; text-align: center;\">等待开拍...</div>\n        </div>\n\n        <!-- 操作按钮 -->\n        <div id=\"auction-controls\" style=\"display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 10px;\">\n            <button class=\"form-button-secondary\" onclick=\"placeBid(1.1)\" style=\"background: #333; color: white; border: 1px solid #555;\">+10%</button>\n            <button class=\"form-button-secondary\" onclick=\"placeBid(1.5)\" style=\"background: #333; color: white; border: 1px solid #555;\">+50%</button>\n            <button class=\"form-button\" onclick=\"placeBid('custom')\" style=\"background: linear-gradient(135deg, #d4af37, #f2d06b); color: black; font-weight: bold; border: none;\">出价</button>\n        </div>\n    </div>\n</div>\n<div id=\"todo-list-screen\" class=\"screen\" style=\"background-color: #f2f2f7;\">\n    <div class=\"header\">\n        <span class=\"back-btn\" id=\"todo-list-back-btn\">‹</span>\n        <span>待办事项</span>\n        <span class=\"action-btn\" id=\"add-todo-btn\" style=\"font-size: 24px;\">+</span>\n    </div>\n    \n    <div class=\"todo-date-navigator\">\n        <button id=\"todo-prev-day-btn\">‹</button>\n        <div id=\"todo-current-date-display\">今天</div>\n        <button id=\"todo-next-day-btn\">›</button>\n    </div>\n\n    <div id=\"char-todo-generate-row\" hidden style=\"padding: 0 15px;\">\n        <button type=\"button\" id=\"char-todo-generate\" class=\"form-button\">生成 Char 待办</button>\n    </div>\n    <div id=\"todo-list-container\" class=\"list-container\" style=\"padding: 15px;\">\n        </div>\n</div>\n<div id=\"green-river-screen\" class=\"screen gr-theme\">\n    <div class=\"gr-header\">\n    <button class=\"gr-icon-btn\" onclick=\"showScreen('home-screen')\">\n        <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M15 18l-6-6 6-6\"/></svg>\n    </button>\n    \n    <span class=\"gr-title\">Green River</span>\n    \n    <div class=\"gr-header-actions\">\n        <button class=\"gr-icon-btn\" onclick=\"openAuthorManager()\" title=\"作者管理\">\n            <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2\"></path><circle cx=\"12\" cy=\"7\" r=\"4\"></circle></svg>\n        </button>\n        <button class=\"gr-icon-btn\" onclick=\"createNewStory()\" title=\"新建作品\">\n            <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"></line><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"></line></svg>\n        </button>\n    </div>\n</div>\n    \n    <div class=\"gr-content-area\">\n        <div class=\"gr-section-header\">\n            <span class=\"gr-section-title\">书架 Library</span>\n        </div>\n        <input id=\"gr-library-search\" class=\"gr-input gr-library-search\" type=\"search\" placeholder=\"搜索书名、题材或标签\">\n        <div id=\"gr-book-list\" class=\"gr-grid-list\">\n            </div>\n    </div>\n</div>\n\n<div id=\"gr-author-screen\" class=\"screen gr-theme\">\n    <div class=\"gr-header\">\n        <button class=\"gr-icon-btn\" onclick=\"showScreen('green-river-screen')\">\n            <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M15 18l-6-6 6-6\"/></svg>\n        </button>\n        <span class=\"gr-title\">Authors</span>\n        <div class=\"gr-header-actions\">\n            <button class=\"gr-icon-btn\" onclick=\"addAuthor()\">\n                <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"></line><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"></line></svg>\n            </button>\n        </div>\n    </div>\n    <div class=\"gr-content-area\" id=\"gr-author-list\"></div>\n</div>\n\n<div id=\"gr-reader-screen\" class=\"screen gr-theme\">\n    <div class=\"gr-header\">\n        <button class=\"gr-icon-btn\" onclick=\"showScreen('green-river-screen')\">\n            <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M15 18l-6-6 6-6\"/></svg>\n        </button>\n        <div style=\"display:flex; flex-direction:column; align-items:center;\">\n             <span class=\"gr-title\" id=\"gr-book-name-display\" style=\"font-size:14px; opacity:0.7;\">书名</span>\n             <span class=\"gr-title\" id=\"gr-chapter-title-display\" style=\"font-size:16px; font-weight:bold;\">第一章</span>\n        </div>\n        <div class=\"gr-reader-header-actions\">\n        <button class=\"gr-mode-toggle-btn\" id=\"gr-reading-mode-toggle\" type=\"button\" title=\"切换沉浸阅读\">阅读</button>\n        <button class=\"gr-icon-btn\" onclick=\"openStorySettings()\" title=\"设定\">\n            <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"3\"></circle><path d=\"M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z\"></path></svg>\n        </button>\n        </div>\n    </div>\n\n    <div id=\"gr-sidebar-overlay\" onclick=\"closeChapterList()\"></div>\n    <div id=\"gr-chapter-sidebar\">\n        <div class=\"gr-sidebar-header\">\n            <span>目录 Contents</span>\n            <span id=\"gr-total-chapters\" style=\"font-size:12px; color:#888;\">共 0 章</span>\n        </div>\n        <div id=\"gr-chapter-list-content\">\n            </div>\n    </div>\n    \n    <div class=\"gr-reader-content\" id=\"gr-reader-content\">\n        </div>\n\n    <div id=\"gr-reader-comments-popup\" class=\"gr-comments-popup\" style=\"display:none;\">\n        <div class=\"gr-comments-popup-inner\">\n            <div class=\"gr-comments-popup-header\">\n                <span class=\"gr-comments-popup-title\">💬 读者评论</span>\n                <button type=\"button\" class=\"gr-comments-popup-close\" aria-label=\"关闭\">&times;</button>\n            </div>\n            <div class=\"gr-comments-popup-list\"></div>\n            <div class=\"gr-comments-composer\">\n                <input id=\"gr-user-comment-input\" type=\"text\" maxlength=\"300\" placeholder=\"写一条段评…\">\n                <button id=\"gr-user-comment-submit\" type=\"button\">发送</button>\n            </div>\n        </div>\n    </div>\n\n    <div class=\"gr-control-panel\">\n        <div id=\"gr-pagination-controls\" style=\"display:flex; justify-content:space-between; align-items:center; width:100%;\">\n            <button class=\"gr-text-btn\" id=\"gr-prev-chapter-btn\">上一章</button>\n            <button class=\"gr-icon-btn\" id=\"gr-menu-btn\" onclick=\"openChapterList()\">\n                <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"8\" y1=\"6\" x2=\"21\" y2=\"6\"></line><line x1=\"8\" y1=\"12\" x2=\"21\" y2=\"12\"></line><line x1=\"8\" y1=\"18\" x2=\"21\" y2=\"18\"></line><line x1=\"3\" y1=\"6\" x2=\"3.01\" y2=\"6\"></line><line x1=\"3\" y1=\"12\" x2=\"3.01\" y2=\"12\"></line><line x1=\"3\" y1=\"18\" x2=\"3.01\" y2=\"18\"></line></svg>\n            </button>\n            <button class=\"gr-text-btn\" id=\"gr-next-chapter-btn\">下一章</button>\n        </div>\n\n        <div id=\"gr-creator-tools\" class=\"gr-creator-tools\" style=\"display:none;\">\n            <button type=\"button\" id=\"gr-story-bible-btn\" class=\"gr-tool-btn\">剧情档案</button>\n            <button type=\"button\" id=\"gr-new-chapter-btn\" class=\"gr-tool-btn\">手动新章</button>\n            <button type=\"button\" id=\"gr-edit-chapter-btn\" class=\"gr-tool-btn\">编辑正文</button>\n            <button type=\"button\" id=\"gr-diagnose-btn\" class=\"gr-tool-btn\">本章诊断</button>\n            <button type=\"button\" id=\"gr-revisions-btn\" class=\"gr-tool-btn\">修订记录</button>\n            <button type=\"button\" id=\"gr-regenerate-comments-btn\" class=\"gr-tool-btn\">重生成段评</button>\n            <button type=\"button\" id=\"gr-create-branch-btn\" class=\"gr-tool-btn\">创建分支</button>\n        </div>\n        <div id=\"gr-writing-controls\" style=\"display:none; gap:8px; align-items:flex-end; width:100%; margin-top:8px;\">\n             <div class=\"gr-input-group gr-direction-group\" style=\"flex-grow:1;\">\n                <button type=\"button\" id=\"gr-writing-mode-trigger\" class=\"gr-select gr-writing-mode\" aria-haspopup=\"dialog\" aria-expanded=\"false\">自然续写</button>\n                <select id=\"gr-writing-mode\" aria-hidden=\"true\" tabindex=\"-1\" hidden>\n                    <option value=\"continue\">自然续写</option>\n                    <option value=\"direction\">按方向续写</option>\n                    <option value=\"extend\">延长当前场景</option>\n                    <option value=\"transition\">补写自然过渡</option>\n                    <option value=\"dialogue\">加强人物对话</option>\n                </select>\n                <textarea id=\"gr-direction-input\" class=\"gr-input\" rows=\"2\" placeholder=\"可选：输入本章要发生什么、必须包含或不要出现的内容\"></textarea>\n            </div>\n            <button id=\"gr-reroll-btn\" class=\"gr-main-btn\" style=\"background-color:#F4F4F5; color:#666; border:1px solid #ddd; padding: 10px;\" title=\"重写本章\">\n                <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M23 4v6h-6\"></path><path d=\"M1 20v-6h6\"></path><path d=\"M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15\"></path></svg>\n            </button>\n            <button id=\"gr-generate-btn\" class=\"gr-main-btn\">\n                <span id=\"gr-gen-text\">续写</span>\n                <svg id=\"gr-gen-icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                    <line x1=\"22\" y1=\"2\" x2=\"11\" y2=\"13\"></line>\n                    <polygon points=\"22 2 15 22 11 13 2 9 22 2\"></polygon>\n                </svg>\n            </button>\n        </div>\n        <div id=\"gr-writing-mode-modal\" class=\"gr-writing-mode-modal\" aria-hidden=\"true\">\n            <div class=\"gr-writing-mode-dialog\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"gr-writing-mode-title\">\n                <div class=\"gr-writing-mode-dialog-header\"><span id=\"gr-writing-mode-title\">选择写作方式</span><button type=\"button\" id=\"gr-writing-mode-close\" class=\"gr-writing-mode-close\" aria-label=\"关闭\">×</button></div>\n                <div id=\"gr-writing-mode-options\" class=\"gr-writing-mode-options\">\n                    <button type=\"button\" data-value=\"continue\">自然续写<span>承接上一章，自然推进剧情</span></button>\n                    <button type=\"button\" data-value=\"direction\">按方向续写<span>按照你给出的剧情方向展开</span></button>\n                    <button type=\"button\" data-value=\"extend\">延长当前场景<span>继续描写当前场景，不急着切换</span></button>\n                    <button type=\"button\" data-value=\"transition\">补写自然过渡<span>补足场景之间的连接和转折</span></button>\n                    <button type=\"button\" data-value=\"dialogue\">加强人物对话<span>让对话更有潜台词和推进感</span></button>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n<!-- 邮箱主界面 -->\n<div id=\"email-screen\" class=\"screen mail-theme\" style=\"background-color: #FFFFFF;\">\n    <div class=\"mail-header\">\n        <button class=\"mail-icon-btn\" onclick=\"showScreen('home-screen')\">\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M15 19l-7-7 7-7\"/></svg>\n            <span class=\"mail-back-label\">返回</span>\n        </button>\n        <div class=\"mail-header-actions\">\n            <button class=\"mail-icon-btn\" onclick=\"openMailContacts()\" title=\"联系人\" aria-label=\"联系人\">\n                <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>\n            </button>\n            <button class=\"mail-icon-btn\" onclick=\"openEmailSettings()\" title=\"邮箱配置\" aria-label=\"邮箱配置\">\n                <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z\"/></svg>\n            </button>\n            <button class=\"mail-icon-btn\" onclick=\"handleQuickReceiveMail()\" title=\"收取新邮件\" aria-label=\"收取新邮件\">\n                <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z\"/><polyline points=\"22,6 12,13 2,6\"/></svg>\n            </button>\n            <button id=\"mail-edit-btn\" class=\"mail-icon-btn mail-text-action\" onclick=\"toggleEmailEditMode()\" title=\"编辑列表\">编辑</button>\n        </div>\n    </div>\n\n    <div style=\"flex-shrink: 0; background-color: #FFFFFF;\">\n        <div class=\"mail-title-row\">\n            <h1 class=\"mail-large-title\" id=\"mail-folder-title\">收件箱</h1>\n            <button class=\"mail-compose-fab\" onclick=\"openMailCompose()\" title=\"写邮件\" aria-label=\"写邮件\">\n                <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 20h9\"/><path d=\"M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z\"/></svg>\n            </button>\n        </div>\n        <div class=\"mail-folder-tabs\" id=\"mail-folder-tabs\" aria-label=\"邮箱文件夹\">\n            <button class=\"active\" data-folder=\"inbox\">收件箱 <span id=\"mail-count-inbox\"></span></button>\n            <button data-folder=\"starred\">星标</button>\n            <button data-folder=\"sent\">已发送</button>\n            <button data-folder=\"drafts\">草稿</button>\n            <button data-folder=\"scheduled\">定时</button>\n            <button data-folder=\"spam\">垃圾邮件</button>\n            <button data-folder=\"trash\">已删除</button>\n        </div>\n        <div class=\"mail-search-bar\">\n            <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#8A8E99\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"></circle><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"></line></svg>\n            <input type=\"text\" placeholder=\"搜索发件人、主题或正文\" id=\"mail-search-input\">\n        </div>\n    </div>\n\n    <div id=\"email-list\" class=\"mail-list-container\"></div>\n    <div id=\"mail-action-bar\" style=\"display: none;\">\n        <div class=\"select-all-btn\" id=\"mail-select-all-btn\">全选</div>\n        <button id=\"mail-delete-selected-btn\" class=\"mail-delete-action-btn\">删除</button>\n    </div>\n</div>\n\n<div id=\"email-detail-screen\" class=\"screen mail-theme\" style=\"background-color: #FFFFFF; display: flex; flex-direction: column;\">\n    <div class=\"mail-detail-header\">\n        <button class=\"mail-icon-btn\" onclick=\"closeEmailDetail()\">\n            <svg width=\"21\" height=\"21\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#007AFF\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M15 19l-7-7 7-7\"/></svg>\n            <span style=\"color: #007AFF; font-size: 15px; margin-left: 2px;\">收件箱</span>\n        </button>\n        \n        <div class=\"mail-header-actions\">\n            <button class=\"mail-icon-btn\" id=\"mail-detail-star-btn\" title=\"星标\" aria-label=\"星标\">\n                <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#007AFF\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg>\n            </button>\n            <button class=\"mail-icon-btn\" id=\"forward-email-btn\" title=\"转发到聊天\">\n                <svg width=\"21\" height=\"21\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#007AFF\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"22\" y1=\"2\" x2=\"11\" y2=\"13\"></line><polygon points=\"22 2 15 22 11 13 2 9 22 2\"></polygon></svg>\n            </button>\n            <button class=\"mail-icon-btn\" id=\"delete-email-btn\" title=\"删除邮件\" style=\"color: #ff3b30;\">\n                <svg width=\"21\" height=\"21\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"3 6 5 6 21 6\"></polyline><path d=\"M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2\"></path></svg>\n            </button>\n        </div>\n    </div>\n    \n    <div class=\"mail-detail-content\" id=\"mail-detail-scroll\">\n        <div class=\"mail-meta-header\">\n            <div class=\"mail-subject-line\" id=\"mail-detail-subject\">Subject</div>\n            <div class=\"mail-meta-row\">\n                <div class=\"mail-sender-avatar\" id=\"mail-detail-avatar\"></div>\n                <div class=\"mail-meta-info\">\n                    <div class=\"mail-from-row\">\n                        <span class=\"mail-from-name\" id=\"mail-detail-from\">Sender Name</span>\n                        <span class=\"mail-time\" id=\"mail-detail-time\">Today</span>\n                    </div>\n                    <div class=\"mail-to-row\">To: <span id=\"mail-detail-to\">Me</span></div>\n                </div>\n            </div>\n        </div>\n        <div id=\"mail-thread-list\"></div>\n        <div class=\"mail-body-text\" id=\"mail-detail-body\"></div>\n        <div id=\"mail-detail-attachments\" class=\"mail-attachment-list\"></div>\n        <div id=\"mail-detail-status\" class=\"mail-detail-status\"></div>\n        <section id=\"mail-reply-progress\" class=\"mail-reply-progress\" hidden aria-live=\"polite\"></section>\n        <section id=\"mail-generated-reply-tools\" class=\"mail-generated-reply-tools\" hidden>\n            <div class=\"mail-generated-reply-actions\">\n                <button id=\"mail-edit-generated-btn\" class=\"mail-secondary-btn\" type=\"button\">手动编辑</button>\n                <button id=\"mail-regenerate-btn\" class=\"mail-secondary-btn\" type=\"button\">重说</button>\n                <button id=\"mail-reply-history-btn\" class=\"mail-secondary-btn\" type=\"button\">历史</button>\n            </div>\n            <div id=\"mail-generated-editor\" class=\"mail-generated-editor\" hidden>\n                <label><span>主题</span><input id=\"mail-edit-generated-subject\" maxlength=\"120\"></label>\n                <label><span>正文</span><textarea id=\"mail-edit-generated-content\"></textarea></label>\n                <div class=\"mail-generated-editor-actions\">\n                    <button id=\"mail-cancel-generated-edit\" class=\"mail-secondary-btn\" type=\"button\">取消</button>\n                    <button id=\"mail-save-generated-edit\" class=\"mail-secondary-btn mail-primary-compact\" type=\"button\">保存</button>\n                </div>\n            </div>\n        </section>\n        <div class=\"mail-detail-actions-row\">\n            <button id=\"mail-reply-btn\" class=\"mail-secondary-btn\">回复</button>\n            <button id=\"mail-contact-btn\" class=\"mail-secondary-btn\">查看联系人</button>\n            <button id=\"mail-move-spam-btn\" class=\"mail-secondary-btn\">垃圾邮件</button>\n        </div>\n    </div>\n</div>\n\n<!-- 写邮件 -->\n<div id=\"email-compose-screen\" class=\"screen mail-theme mail-subscreen\" style=\"background-color: #FFFFFF;\">\n    <div class=\"mail-detail-header mail-compose-header\">\n        <button class=\"mail-icon-btn mail-text-action\" id=\"mail-compose-cancel-btn\">取消</button>\n        <span class=\"mail-centered-title\" id=\"mail-compose-title\">新邮件</span>\n        <button class=\"mail-icon-btn mail-text-action mail-send-action\" id=\"mail-compose-send-btn\">发送</button>\n    </div>\n    <div class=\"mail-compose-scroll\">\n        <label class=\"mail-compose-row\"><span>发件人</span><select id=\"mail-compose-account\"></select></label>\n        <label class=\"mail-compose-row\"><span>收件人</span><select id=\"mail-compose-recipient\"></select></label>\n        <label class=\"mail-compose-row\"><span>地址</span><input id=\"mail-compose-recipient-address\" type=\"email\" placeholder=\"name@example.test\"></label>\n        <label class=\"mail-compose-row\"><span>抄送</span><input id=\"mail-compose-cc\" type=\"text\" placeholder=\"可选，用逗号分隔\"></label>\n        <label class=\"mail-compose-row\"><span>密送</span><input id=\"mail-compose-bcc\" type=\"text\" placeholder=\"可选，用逗号分隔\"></label>\n        <label class=\"mail-compose-row mail-subject-row\"><span>主题</span><input id=\"mail-compose-subject\" maxlength=\"120\" placeholder=\"邮件主题\"></label>\n        <textarea id=\"mail-compose-body\" class=\"mail-compose-body\" placeholder=\"写下邮件正文……\"></textarea>\n        <div class=\"mail-compose-tools\">\n            <label class=\"mail-tool-btn\" for=\"mail-compose-attachment-input\">\n                <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48\"/></svg><span>附件</span>\n            </label>\n            <input id=\"mail-compose-attachment-input\" type=\"file\" multiple hidden>\n            <button class=\"mail-tool-btn\" id=\"mail-ai-assist-btn\"><span>AI 辅助</span></button>\n            <label class=\"mail-compact-toggle\"><input type=\"checkbox\" id=\"mail-compose-anonymous\"><span>匿名</span></label>\n            <label class=\"mail-compact-toggle\"><input type=\"checkbox\" id=\"mail-compose-receipt\"><span>回执</span></label>\n        </div>\n        <div id=\"mail-compose-attachments\" class=\"mail-attachment-list\"></div>\n        <label class=\"mail-compose-row mail-reply-mode-row\"><span>回信</span><select id=\"mail-compose-reply-mode\">\n            <option value=\"default\">跟随默认设置</option>\n            <option value=\"instant\">立即回复</option>\n            <option value=\"fixed\">等待指定时间</option>\n            <option value=\"random\">随机等待</option>\n            <option value=\"manual\">仅手动调用</option>\n        </select></label>\n        <div id=\"mail-compose-reply-options\" class=\"mail-compose-reply-options\" hidden>\n            <label id=\"mail-compose-fixed-wrap\"><span>等待分钟</span><input id=\"mail-compose-fixed-delay\" type=\"number\" min=\"0\" max=\"10080\" value=\"10\"></label>\n            <div id=\"mail-compose-random-wrap\" class=\"mail-compose-random-wrap\"><label><span>最短分钟</span><input id=\"mail-compose-random-min\" type=\"number\" min=\"0\" max=\"10080\" value=\"2\"></label><label><span>最长分钟</span><input id=\"mail-compose-random-max\" type=\"number\" min=\"0\" max=\"10080\" value=\"30\"></label></div>\n        </div>\n        <label class=\"mail-schedule-row\"><input type=\"checkbox\" id=\"mail-compose-schedule-toggle\"><span>定时发送</span><input type=\"datetime-local\" id=\"mail-compose-scheduled-at\" disabled></label>\n        <p class=\"mail-compose-hint\" id=\"mail-compose-hint\">取消时可选择保存为草稿；AI 辅助不会自动发送。</p>\n    </div>\n</div>\n\n<!-- 联系人与笔友 -->\n<div id=\"mail-contacts-screen\" class=\"screen mail-theme mail-subscreen\" style=\"background-color: #FFFFFF;\">\n    <div class=\"mail-detail-header\">\n        <button class=\"mail-icon-btn\" onclick=\"closeMailContacts()\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M15 19l-7-7 7-7\"/></svg><span class=\"mail-back-label\">邮箱</span></button>\n        <span class=\"mail-centered-title\">联系人</span>\n        <button class=\"mail-icon-btn mail-text-action\" onclick=\"openMailCompose({ recipientMode: 'random' })\">漂流信</button>\n    </div>\n    <div class=\"mail-contact-filter\" id=\"mail-contact-filter\">\n        <button class=\"active\" data-filter=\"all\">全部</button>\n        <button data-filter=\"penpal\">笔友</button>\n        <button data-filter=\"suspicious\">可疑</button>\n        <button data-filter=\"lost_contact\">失联</button>\n        <button data-filter=\"blocked\">已拉黑</button>\n    </div>\n    <div id=\"mail-contact-list\" class=\"mail-contact-list\"></div>\n    <div class=\"mail-public-boxes\">\n        <div class=\"mail-section-label\">公共邮箱</div>\n        <div id=\"mail-public-box-list\"></div>\n    </div>\n</div>\n\n<div id=\"mail-contact-detail-screen\" class=\"screen mail-theme mail-subscreen\" style=\"background-color: #FFFFFF;\">\n    <div class=\"mail-detail-header\">\n        <button class=\"mail-icon-btn\" onclick=\"closeMailContactDetail()\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M15 19l-7-7 7-7\"/></svg><span class=\"mail-back-label\">联系人</span></button>\n        <span class=\"mail-centered-title\">联系人资料</span>\n        <button class=\"mail-icon-btn mail-text-action\" id=\"mail-contact-write-btn\" onclick=\"openMailCompose({ contactId: mailState.currentContactId })\">写信</button>\n    </div>\n    <div class=\"mail-contact-detail\" id=\"mail-contact-detail\"></div>\n</div>\n\n<!-- 邮件生成器配置弹窗 -->\n<div id=\"email-generator-modal\" class=\"modal\">\n    <div class=\"modal-content\" style=\"height: 85%; background-color: #FAFAF9; border-radius: 20px;\">\n        <div class=\"mail-modal-header\">\n            <span>收件箱配置</span>\n        </div>\n        <div class=\"modal-body\" style=\"padding: 20px;\">\n            \n            <!-- 1. 身份设定 -->\n            <div class=\"gr-form-group\">\n                <label>收件人身份 (User Persona)</label>\n                \n                <select id=\"mail-user-persona-select\" class=\"gr-input\" style=\"margin-bottom: 8px; padding: 8px; border:1px solid #ddd;\">\n                    <option value=\"\">-- 仅使用下方关键词 --</option>\n                </select>\n\n                <input type=\"text\" id=\"mail-user-mask\" class=\"gr-input\" placeholder=\"例如：侦探、公司高管、神秘人...\" value=\"普通用户\">\n                <p style=\"font-size:11px; color:#999; margin-top:5px;\">选择预设可提供详细背景，下方输入框用于定义当前具体的社会身份。</p>\n            </div>\n\n            <!-- 2. 世界观设定 -->\n            <div class=\"gr-form-group\">\n                <label>邮件系统背景 (World Context)</label>\n                <textarea id=\"mail-world-context\" class=\"gr-input\" rows=\"3\" placeholder=\"例如：赛博朋克黑客论坛通知、维多利亚时期的信件、现代职场垃圾邮件...\"></textarea>\n            </div>\n\n            <!-- 3. 发件人来源 -->\n            <div class=\"gr-form-group\">\n                <label>发件人来源 (多选)</label>\n                <div class=\"gr-checkbox-list\" id=\"mail-sender-list\">\n                    <!-- JS 动态填充角色和 NPC -->\n                </div>\n                <label style=\"margin-top:10px; display:flex; align-items:center;\">\n                    <input type=\"checkbox\" id=\"mail-allow-random-npc\" checked> 允许生成随机陌生人/垃圾邮件\n                </label>\n            </div>\n\n            <!-- 4. 关联上下文 -->\n            <div class=\"gr-form-group\">\n                <label>关联记忆与世界书</label>\n                <div class=\"gr-checkbox-list\" id=\"mail-context-list\">\n                    <!-- JS 动态填充世界书 -->\n                </div>\n            </div>\n            <div class=\"gr-form-group\">\n                <label>生成数量</label>\n                <div style=\"display: flex; align-items: center; gap: 10px;\">\n                    <input type=\"number\" id=\"mail-gen-count\" class=\"gr-input\" value=\"3\" min=\"1\" max=\"10\" style=\"flex:1;\">\n                    <span style=\"font-size: 13px; color: #888;\">封</span>\n                </div>\n            </div>\n            <div class=\"gr-form-group\">\n                <label>陌生人通信与后台活动</label>\n                <label class=\"mail-setting-switch\"><span>允许后台处理到期回信</span><input type=\"checkbox\" id=\"mail-background-enabled\" checked></label>\n                <label class=\"mail-setting-switch\"><span>允许陌生人发展为长期笔友</span><input type=\"checkbox\" id=\"mail-penpal-enabled\" checked></label>\n                <label class=\"mail-setting-switch\"><span>允许联系人提出交换联系方式</span><input type=\"checkbox\" id=\"mail-friend-enabled\" checked></label>\n                <label class=\"mail-setting-switch\"><span>允许悬疑与身份存疑内容</span><input type=\"checkbox\" id=\"mail-mystery-enabled\" checked></label>\n                <label class=\"mail-setting-switch\"><span>允许荒诞世界邮件</span><input type=\"checkbox\" id=\"mail-absurd-enabled\" checked></label>\n                <label class=\"mail-setting-switch\"><span>允许陌生人暧昧内容</span><input type=\"checkbox\" id=\"mail-flirt-enabled\"></label>\n                <label class=\"mail-setting-field\"><span>默认回信方式</span><select id=\"mail-reply-mode\" class=\"gr-input\">\n                    <option value=\"instant\">立即回复</option>\n                    <option value=\"fixed\">等待指定时间</option>\n                    <option value=\"random\">随机等待</option>\n                    <option value=\"manual\">仅手动调用</option>\n                </select></label>\n                <label class=\"mail-setting-field\" id=\"mail-fixed-delay-wrap\"><span>固定等待（分钟）</span><input type=\"number\" id=\"mail-reply-fixed-delay\" min=\"0\" max=\"10080\" value=\"10\"></label>\n                <div class=\"mail-delay-grid\"><label>最短回信（分钟）<input type=\"number\" id=\"mail-reply-delay-min\" min=\"0\" max=\"10080\" value=\"2\"></label><label>最长回信（分钟）<input type=\"number\" id=\"mail-reply-delay-max\" min=\"0\" max=\"10080\" value=\"30\"></label></div>\n                <p class=\"mail-setting-note\">陌生人均为本地 AI 虚构角色，不会进入真人联机好友列表。</p>\n            </div>\n        </div>\n        <div class=\"modal-footer\" style=\"border-top: 1px solid #E5E5E5; display:flex; gap:15px;\">\n            <button class=\"cancel\" style=\"background:#F5F5F7; color:#000; border:none;\" onclick=\"document.getElementById('email-generator-modal').classList.remove('visible')\">取消</button>\n            <button class=\"cancel\" style=\"background:#EEF5FF; color:#007AFF; border:none;\" id=\"save-mail-settings-btn\">保存设置</button>\n            <button class=\"save\" style=\"background:#007AFF; color:#fff; border:none;\" id=\"start-generate-email-btn\">接收邮件</button>\n        </div>\n    </div>\n</div>\n\n    <div id=\"shopping-screen\" class=\"screen\">\n      <div class=\"header\">\n        <div class=\"header-left-actions\"> <span class=\"back-btn\" id=\"shopping-back-btn\">‹</span> <span class=\"action-btn\" id=\"generate-shopping-items-btn\" title=\"AI生成商品\"> <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" stroke=\"currentColor\"\n              stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <path d=\"M20 11A8.1 8.1 0 0 0 4.5 9M4 5v4h4\"></path>\n              <path d=\"M4 13a8.1 8.1 0 0 0 15.5 2m.5 4v-4h-4\"></path>\n            </svg> </span> <span class=\"action-btn\" id=\"shopping-settings-btn\" title=\"生成设置\"> <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <path\n                d=\"M19.14,12.94c0.04-0.3,0.06-0.61,0.06-0.94c0-0.32-0.02-0.64-0.07-0.94l2.03-1.58c0.18-0.14,0.23-0.41,0.12-0.61 l-1.92-3.32c-0.12-0.22-0.37-0.29-0.59-0.22l-2.39,0.96c-0.5-0.38-1.03-0.7-1.62-0.94L14.4,2.81c-0.04-0.24-0.24-0.41-0.48-0.41 h-3.84c-0.24,0-0.44,0.17-0.48,0.41L9.12,4.84c-0.59,0.24-1.12,0.56-1.62,0.94L5.11,4.82c-0.22-0.08-0.47,0-0.59,0.22l-1.92,3.32 c-0.12,0.22-0.07,0.47,0.12,0.61l2.03,1.58C4.84,11.36,4.82,11.68,4.82,12s0.02,0.64,0.07,0.94l-2.03,1.58 c-0.18,0.14-0.23,0.41-0.12,0.61l1.92,3.32c0.12,0.22,0.37,0.29,0.59,0.22l2.39-0.96c0.5,0.38,1.03,0.7,1.62,0.94l0.48,2.03 c0.04,0.24,0.24,0.41,0.48,0.41h3.84c0.24,0,0.44-0.17,0.48-0.41l0.48-2.03c0.59-0.24,1.12-0.56,1.62-0.94l2.39,0.96 c0.22,0.08,0.47,0,0.59-0.22l1.92-3.32c0.12-0.22,0.07-0.47-0.12-0.61L19.14,12.94z M12,15.6c-1.98,0-3.6-1.62-3.6-3.6 s1.62-3.6,3.6-3.6s3.6,1.62,3.6,3.6S13.98,15.6,12,15.6z\">\n              </path>\n            </svg> </span> <span class=\"action-btn\" id=\"delete-current-category-btn\" title=\"删除当前分类\" style=\"display: none; color: rgb(255, 59, 48);\"> <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" stroke=\"currentColor\" stroke-width=\"2\"\n              stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <path d=\"M21 4H8l-7 8 7 8h13a2 2 0 0 0 2-2V6a2 2 0 0 0-2-2z\"></path>\n              <line x1=\"18\" y1=\"9\" x2=\"12\" y2=\"15\"></line>\n              <line x1=\"12\" y1=\"9\" x2=\"18\" y2=\"15\"></line>\n            </svg> </span> </div> <span>购物中心</span>\n        <div class=\"header-actions\"> <span class=\"action-btn\" id=\"manage-products-btn\" title=\"管理商品\" style=\"color: var(--text-primary);\"> <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"\n              stroke-linejoin=\"round\">\n              <path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"></path>\n            </svg> </span> <span class=\"action-btn\" id=\"add-new-product-btn\" title=\"添加新商品\"> <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <circle cx=\"12\" cy=\"12\" r=\"10\"></circle>\n              <line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"16\"></line>\n              <line x1=\"8\" y1=\"12\" x2=\"16\" y2=\"12\"></line>\n            </svg> </span> <span class=\"action-btn\" id=\"go-to-cart-btn\" title=\"查看购物车\"> <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <circle cx=\"9\" cy=\"21\" r=\"1\"></circle>\n              <circle cx=\"20\" cy=\"21\" r=\"1\"></circle>\n              <path d=\"M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6\"></path>\n            </svg> <span id=\"cart-count\">0</span> </span> </div>\n      </div>\n      <div id=\"product-category-tabs\"></div>\n      <div id=\"product-grid\" class=\"list-container\"> </div>\n      <div id=\"shopping-action-bar\"> <label class=\"select-all-label\"> <input type=\"checkbox\" id=\"select-all-products-checkbox\"> 全选 </label> <button id=\"delete-selected-products-btn\" class=\"action-bar-btn\">删除 (0)</button> </div>\n    </div>\n    <div id=\"product-detail-screen\" class=\"screen\">\n      <div class=\"header\"> <span class=\"back-btn\" id=\"product-detail-back-btn\">‹</span> <span>商品详情</span> <span style=\"width: 30px;\"></span> </div>\n      <div id=\"product-detail-content\" class=\"list-container\"> </div>\n      <div id=\"product-detail-footer\"> <button class=\"footer-btn add-to-cart-detail-btn\">加入购物车</button> <button class=\"footer-btn buy-now-btn\">立即购买</button> </div>\n    </div>\n    <div id=\"cart-screen\" class=\"screen\">\n      <div class=\"header\"> <span class=\"back-btn\" id=\"cart-back-btn\">‹</span> <span id=\"cart-title\">购物车(0)</span> <span class=\"action-btn\" id=\"clear-cart-btn\">清空</span> </div>\n      <div id=\"cart-items-list\" class=\"list-container\"> </div>\n      <div id=\"cart-footer\"> <label class=\"select-all-label\"><input type=\"checkbox\" id=\"select-all-cart-items\"> 全选</label>\n        <div class=\"cart-summary\">\n          <div id=\"cart-total\">合计: ¥0.00</div> <span class=\"cart-subtext\">不含运费</span>\n        </div> <button id=\"checkout-btn\">结算(0)</button>\n      </div>\n    </div>\n    <div id=\"product-editor-modal\" class=\"modal\">\n      <div class=\"modal-content\" style=\"height: 85%;\">\n        <div class=\"modal-header\"> <span id=\"product-editor-title\">添加商品</span> </div>\n        <div class=\"modal-body\">\n          <div class=\"form-group\"> <label>商品图片</label>\n            <div class=\"avatar-upload\"> <img id=\"product-image-preview\" src=\"https://s3plus.meituan.net/opapisdk/op_ticket_885190757_1756206115802_qdqqd_0c99bh.jpeg\"> <button onclick=\"document.getElementById('product-image-input').click()\">上传图片</button> <input type=\"file\" id=\"product-image-input\"\n                accept=\"image/*\" hidden> </div>\n          </div>\n          <div class=\"form-group\"> <label for=\"product-name-input\">商品名称</label> <input type=\"text\" id=\"product-name-input\"> </div>\n          <div class=\"form-group\"> <label for=\"product-category-select\">商品分类</label>\n            <div style=\"display: flex; align-items: center; gap: 10px;\"> <select id=\"product-category-select\" style=\"flex-grow: 1;\"></select> <button id=\"manage-product-categories-btn\" class=\"form-button-secondary\" style=\"margin-top: 0; padding: 12px;\">管理</button> </div>\n          </div>\n          <div class=\"form-group\"> <label for=\"product-price-input\">默认价格 (元)</label> <input type=\"number\" id=\"product-price-input\" min=\"0\" step=\"0.01\"> </div>\n          <div class=\"form-group\"> <label for=\"product-description-input\">商品描述</label> <textarea id=\"product-description-input\" rows=\"3\" placeholder=\"详细介绍一下这个商品...\"></textarea> </div>\n          <hr style=\"opacity: 0.2; margin: 20px 0;\">\n          <div class=\"form-group\"> <label>商品款式</label>\n            <p style=\"font-size: 12px; color: #888; margin-top: -5px; margin-bottom: 10px;\">如果没有添加任何款式，将使用上面的默认价格。</p>\n            <div id=\"product-variations-container\" style=\"display: flex; flex-direction: column; gap: 15px;\"> </div> <button id=\"add-product-variation-btn\" class=\"form-button form-button-secondary\" style=\"margin-top: 15px;\">+ 添加新的一款</button>\n          </div>\n        </div>\n        <div class=\"modal-footer\"> <button class=\"cancel\" id=\"cancel-product-editor-btn\"data-lang-key=\"cancel\">取消</button> <button class=\"save\" id=\"save-product-btn\"data-lang-key=\"save\">保存</button> </div>\n      </div>\n    </div>\n    <div id=\"gift-receipt-modal\" class=\"modal\">\n      <div class=\"modal-content\">\n        <div class=\"modal-header\"> <span>购物小票</span> </div>\n        <div class=\"modal-body\" id=\"gift-receipt-body\"> </div>\n        <div class=\"modal-footer\"> <button class=\"save\" id=\"close-receipt-btn\" style=\"width:100%;\">关闭</button> </div>\n      </div>\n    </div>\n  </div>\n  </div> <input type=\"file\" id=\"import-card-input\" accept=\".json,.png\" multiple style=\"display: none;\"> <input type=\"file\" id=\"import-world-book-input\" accept=\".json,.txt,.zip,.docx\" multiple style=\"display: none;\">\n  <div id=\"persona-library-modal\" class=\"modal\">\n    <div class=\"modal-content\">\n      <div class=\"modal-header\">\n        <span>我的人设库</span>\n        <div style=\"display: flex; gap: 10px;\">\n          <button id=\"import-tavern-persona-btn\" class=\"action-button\">导入</button>\n          <button id=\"add-persona-preset-btn\" class=\"action-button\" data-lang-key=\"add\">添加</button>\n          <button id=\"manage-persona-preset-btn\" class=\"action-button\" data-lang-key=\"manage\">管理</button>\n        </div>\n      </div>\n      <div class=\"modal-body\">\n        <div id=\"persona-library-grid\"></div>\n      </div>\n      <div class=\"modal-footer\">\n        <button class=\"cancel\" id=\"close-persona-library-btn\">关闭</button>\n        <div id=\"persona-manage-actions\" style=\"display: none; gap: 10px;\">\n          <button class=\"action-button\" id=\"select-all-persona-btn\">全选</button>\n          <button class=\"action-button\" id=\"delete-selected-persona-btn\" style=\"background-color: #ff3b30;\">删除</button>\n          <button class=\"cancel\" id=\"cancel-manage-persona-btn\">取消</button>\n        </div>\n      </div>\n    </div>\n  </div>\n  <input type=\"file\" id=\"import-tavern-persona-input\" accept=\".json\" style=\"display: none;\">\n  \n  <!-- 人设操作选择弹窗 -->\n  <div id=\"persona-action-modal\" class=\"modal\">\n    <div class=\"modal-content\" style=\"width: 350px; height: auto;\">\n      <div class=\"modal-header\">\n        <span id=\"persona-action-title\">人设操作</span>\n      </div>\n      <div class=\"modal-body\" style=\"padding: 20px;\">\n        <button class=\"form-button\" id=\"apply-persona-direct-btn\" style=\"width: 100%; margin-bottom: 15px; padding: 15px; font-size: 16px; background: #007AFF; color: white; border: none;\">\n          <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" style=\"vertical-align: middle; margin-right: 8px;\">\n            <polyline points=\"20 6 9 17 4 12\"></polyline>\n          </svg>\n          直接应用\n        </button>\n        <button class=\"form-button\" id=\"edit-persona-first-btn\" style=\"width: 100%; padding: 15px; font-size: 16px; background: #f0f0f0; color: #333; border: none;\">\n          <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" style=\"vertical-align: middle; margin-right: 8px;\">\n            <path d=\"M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7\"></path>\n            <path d=\"M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z\"></path>\n          </svg>\n          编辑后应用\n        </button>\n      </div>\n      <div class=\"modal-footer\">\n        <button class=\"cancel\" id=\"cancel-persona-action-btn\">取消</button>\n      </div>\n    </div>\n  </div>\n  \n  <!-- 批量导入角色卡预览模态框 -->\n  <div id=\"batch-import-preview-modal\" class=\"modal\">\n    <div class=\"modal-content\" style=\"height: 80%; max-width: 900px;\">\n      <div class=\"modal-header\">\n        <span>批量导入角色卡预览</span>\n        <label style=\"font-size: 14px; font-weight: normal; display: flex; align-items: center; gap: 5px;\">\n          <input type=\"checkbox\" id=\"select-all-import-cards\" checked> 全选\n        </label>\n      </div>\n      <div class=\"modal-body\" id=\"batch-import-preview-list\" style=\"padding: 0; overflow-y: auto;\">\n        <!-- 角色卡预览列表将在这里动态生成 -->\n      </div>\n      <div class=\"modal-footer\">\n        <button class=\"cancel\" id=\"cancel-batch-import-btn\">取消</button>\n        <button class=\"save\" id=\"confirm-batch-import-btn\">确认导入</button>\n      </div>\n    </div>\n  </div>\n  \n  <div id=\"tavern-persona-selector-modal\" class=\"modal\">\n    <div class=\"modal-content\" style=\"height: 70%;\">\n      <div class=\"modal-header\">\n        <span>选择要导入的预设</span>\n      </div>\n      <div class=\"modal-body\" style=\"padding: 0;\">\n        <div id=\"tavern-persona-selector-list\" style=\"overflow-y: auto; height: 100%;\"></div>\n      </div>\n      <div class=\"modal-footer\">\n        <button class=\"cancel\" id=\"cancel-tavern-import-btn\">取消</button>\n        <button class=\"save\" id=\"confirm-tavern-import-btn\">确认导入</button>\n      </div>\n    </div>\n  </div>\n  <div id=\"persona-editor-modal\" class=\"modal\">\n    <div class=\"modal-content\">\n      <div class=\"modal-header\"><span id=\"persona-editor-title\">添加人设预设</span></div>\n      <div class=\"modal-body\">\n        <div class=\"form-group\"><label>预设头像</label>\n          <div class=\"avatar-upload\"><img id=\"preset-avatar-preview\"><button onclick=\"document.getElementById('preset-avatar-input').click()\">上传头像</button><input type=\"file\" id=\"preset-avatar-input\" accept=\"image/*\"></div>\n        </div>\n        <div class=\"form-group\"><label for=\"preset-persona-input\">预设人设</label><textarea id=\"preset-persona-input\" rows=\"4\" placeholder=\"在此输入这个人设的详细设定...\"></textarea></div>\n      </div>\n      <div class=\"modal-footer\"><button class=\"cancel\" id=\"cancel-persona-editor-btn\"data-lang-key=\"cancel\">取消</button><button class=\"save\" id=\"save-persona-preset-btn\"data-lang-key=\"save\">保存</button></div>\n    </div>\n  </div>\n  <div id=\"member-settings-modal\" class=\"modal\">\n    <div class=\"modal-content\">\n      <div class=\"modal-header\"><span data-lang-key=\"edit\">编辑群成员</span></div>\n      <div class=\"modal-body\">\n        <div class=\"form-group\"><label for=\"member-name-input\">名字</label><input type=\"text\" id=\"member-name-input\"></div>\n        <div class=\"form-group\"><label for=\"member-persona-input\">人设</label><textarea id=\"member-persona-input\" rows=\"4\"></textarea></div>\n        <div class=\"form-group role-time-zone-control\">\n          <label for=\"member-time-zone-select\">角色所在地 / 时区</label>\n          <input type=\"search\" id=\"member-time-zone-search-input\" aria-label=\"搜索群成员城市或时区\" aria-controls=\"member-time-zone-search-results\" placeholder=\"搜索城市 / 时区…\" class=\"settings-textarea time-zone-search\">\n          <div id=\"member-time-zone-search-results\" class=\"time-zone-search-results\" role=\"group\" aria-label=\"群成员时区搜索结果\" hidden></div>\n          <select id=\"member-time-zone-select\" class=\"settings-select\"><option value=\"\">未设置（按人设与剧情判断）</option><option value=\"follow-user\">跟随我的时区</option></select>\n          <div class=\"settings-desc time-awareness-inline-desc\">可不设置，按人设与剧情判断；关联角色会同步此设置，开启群聊时间感知后生效。</div>\n        </div>\n        <div class=\"form-group\"><label>头像</label>\n          <div class=\"avatar-upload\"><img id=\"member-avatar-preview\"><button onclick=\"document.getElementById('member-avatar-input').click()\">上传头像</button><button class=\"change-frame-btn\" data-type=\"member\">更换头像框</button><input type=\"file\" id=\"member-avatar-input\" accept=\"image/*\"></div>\n        </div>\n        <div class=\"form-group\">\n          <label>MCP 工具权限</label>\n          <div id=\"member-mcp-permission-editor\"></div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><button class=\"cancel\" id=\"cancel-member-settings-btn\"data-lang-key=\"cancel\">取消</button><button class=\"save\" id=\"save-member-settings-btn\"data-lang-key=\"save\">保存</button></div>\n    </div>\n  </div>\n  <div id=\"custom-modal-overlay\">\n    <div id=\"custom-modal\">\n      <div class=\"custom-modal-header\" id=\"custom-modal-title\"></div>\n      <div class=\"custom-modal-body\" id=\"custom-modal-body\"></div>\n      <div class=\"custom-modal-footer\"> <button id=\"custom-modal-cancel\"data-lang-key=\"cancel\">取消</button> <button id=\"custom-modal-confirm\" class=\"confirm-btn\"data-lang-key=\"confirm\">确定</button> </div>\n    </div>\n  </div>\n";
